"use client";

import { useCallback, useEffect, useRef, useState } from "react";

export default function LiveSelfieCapture({
  onSelfie,
}: {
  onSelfie: (selfie: File | null) => void;
}) {
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [file, setFile] = useState<File | null>(null);
  const [cameraOn, setCameraOn] = useState(true);

  const stopCamera = useCallback(() => {
    streamRef.current?.getTracks().forEach((track) => track.stop());
    streamRef.current = null;
    setCameraOn(false);
  }, []);

  const startCamera = useCallback(async () => {
    setError(null);
    try {
      if (!navigator.mediaDevices?.getUserMedia) {
        throw new Error("getUserMedia not supported in this browser.");
      }
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      streamRef.current = stream;
      setCameraOn(true);
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
    } catch {
      setError("Camera unavailable — upload a selfie instead.");
      setCameraOn(false);
    }
  }, []);

  useEffect(() => {
    startCamera();
    return () => {
      streamRef.current?.getTracks().forEach((track) => track.stop());
      streamRef.current = null;
    };
  }, [startCamera]);

  const setSelfieFile = useCallback(
    (f: File) => {
      if (previewUrl) URL.revokeObjectURL(previewUrl);
      setPreviewUrl(URL.createObjectURL(f));
      setFile(f);
      onSelfie(f);
    },
    [onSelfie, previewUrl]
  );

  const captureFrame = useCallback(() => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas || video.videoWidth === 0) return;

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

    canvas.toBlob((blob) => {
      if (!blob) return;
      stopCamera();
      const newFile = new File([blob], `selfie-${Date.now()}.jpg`, {
        type: blob.type || "image/jpeg",
      });
      setSelfieFile(newFile);
    }, "image/jpeg");
  }, [setSelfieFile, stopCamera]);

  const retake = useCallback(() => {
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setPreviewUrl(null);
    setFile(null);
    onSelfie(null);
    setError(null);
    startCamera();
  }, [onSelfie, previewUrl, startCamera]);

  const onFallbackFile = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const f = e.target.files?.[0] ?? null;
      if (f) {
        stopCamera();
        setError(null);
        setSelfieFile(f);
      }
      e.target.value = "";
    },
    [setSelfieFile, stopCamera]
  );

  return (
    <div>
      <div className="relative aspect-[4/3] w-full overflow-hidden rounded-lg bg-black">
        {!previewUrl ? (
          <video
            ref={videoRef}
            autoPlay
            playsInline
            muted
            className="h-full w-full object-cover"
          />
        ) : (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={previewUrl}
            alt="Captured selfie preview"
            className="h-full w-full object-cover"
          />
        )}
        <canvas ref={canvasRef} className="hidden" />
      </div>

      {file && (
        <p className="mt-1 text-xs text-[#4C6B2A]">{file.name} selected</p>
      )}

      {!previewUrl ? (
        <div className="mt-3 flex flex-wrap items-center gap-2">
          {cameraOn && !error ? (
            <button
              type="button"
              onClick={captureFrame}
              className="h-10 rounded-lg bg-[#4C6B2A] px-4 text-sm font-semibold text-white transition-colors hover:bg-[#5d7f35]"
            >
              📷 Capture Selfie
            </button>
          ) : (
            error && (
              <div className="w-full rounded-lg border border-red-300 bg-red-50 px-4 py-3 text-sm text-red-700">
                {error}
              </div>
            )
          )}

          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            className="h-10 rounded-lg border border-[#2B2B2B]/20 bg-white px-4 text-sm font-semibold text-[#2B2B2B] transition-colors hover:bg-[#2B2B2B]/5"
          >
            Upload selfie instead
          </button>

          {!cameraOn && !file && (
            <button
              type="button"
              onClick={startCamera}
              className="h-10 rounded-lg border border-[#2B2B2B]/20 bg-white px-4 text-sm font-semibold text-[#2B2B2B] transition-colors hover:bg-[#2B2B2B]/5"
            >
              Try camera again
            </button>
          )}

          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            capture="user"
            onChange={onFallbackFile}
            className="hidden"
          />
        </div>
      ) : (
        <div className="mt-3">
          <button
            type="button"
            onClick={retake}
            className="h-10 rounded-lg border border-[#2B2B2B]/20 bg-white px-4 text-sm font-semibold text-[#2B2B2B] transition-colors hover:bg-[#2B2B2B]/5"
          >
            Retake
          </button>
        </div>
      )}
    </div>
  );
}